def queen_attacks(r, c, R, C):
    """Returns a set of coordinates attacked by a queen at (r, c) on an R x C board."""
    attacks = set()
    # Horizontal and Vertical
    for i in range(R):
        if i != r:
            attacks.add((i, c))
    for j in range(C):
        if j != c:
            attacks.add((r, j))
    # Diagonals
    for i in range(R - 1, -1, -1):
        for j in range(C - 1, -1, -1):
            if i != r and j != c and abs(i - r) == abs(j - c):
                attacks.add((i, j))
