class ChessGame:
    def __init__(self, size=8):
        self.N = size
        # 0: Empty, 1: Knight, 2: Queen
        self.board = [[0] * self.N for _ in range(self.N)]
        self.knights = []  # List of (r, c) for knights
        self.queens = []   # List of (r, c) for queens
        self.knights_placed = 0

    def is_valid(self, r, c):
        return 0 <= r < self.N and 0 <= c < self.N

    def get_knight_attacks(self, r, c):
        """Returns list of (r', c') attacked by a knight at (r, c)."""
        moves = [
            (2, 1), (2, -1), (-2, 1), (-2, -1),
            (1, 2), (1, -2), (-1, 2), (-1, -2)
        ]
        attacks = []
        for dr, dc in moves:
            nr, nc = r + dr, c + dc
            if self.is_valid(nr, nc):
                attacks.append((nr, nc))
        return attacks

    def is_knight_placement_valid(self, r, c):
        """Checks if placing a knight at (r, c) is valid relative to existing knights."""
        if self.board[r][c] != 0:
            return False # Square must be empty

        # Check if (r, c) is attacked by any existing knight
        for kr, kc in self.knights:
            if (r, c) in self.get_knight_attacks(kr, kc):
                return False
        return True

    def get_valid_horst_moves(self):
        """Returns a list of (r, c) where Horst can place a knight."""
        valid_moves = []
        for r in range(self.N):
            for c in range(self.N):
                if self.is_knight_placement_valid(r, c):
                    valid_moves.append((r, c))
        return valid_moves

    def make_horst_move(self, r, c):
        """Places a knight at (r, c) and updates state."""
        if not self.is_knight_placement_valid(r, c):
            raise ValueError("Invalid knight move.")
        self.board[r][c] = 1
        self.knights.append((r, c))
        self.knights_placed += 1

    def get_empty_squares(self):
        """Returns a list of (r, c) that are currently empty."""
        empty = []
        for r in range(self.N):
            for c in range(self.N):
                if self.board[r][c] == 0:
                    empty.append((r, c))
        return empty

    def make_queenie_move(self, r, c):
        """Places a queen at (r, c) and updates state."""
        if self.board[r][c] != 0:
            raise ValueError("Invalid queen move. Square is occupied.")
        self.board[r][c] = 2
        self.queens.append((r, c))

